"""Build the public static site. Edit page content here and presentation in site.css."""
from pathlib import Path
from html import escape, unescape
import re, shutil

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
NAV=[('index.html','Home'),('howtoplay.html','How to play'),('world.html','World'),('docs.html','Help'),('maps.html','Maps'),('news.html','News')]

def page(filename,title,content):
    links=''.join(f'<a href="/{path}"'+(' aria-current="page"' if path==filename else '')+f'>{label}</a>' for path,label in NAV)
    terminal_assets='''<link rel="stylesheet" href="/vendor/xterm.css"><link rel="stylesheet" href="/terminal.css">
<script defer src="/vendor/xterm.js"></script><script defer src="/vendor/addon-fit.js"></script><script defer src="/terminal.js"></script>''' if filename=='playnow.html' else ''
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} | The Savage Soul</title><meta name="description" content="The Savage Soul: Scorched Earth. A free text MUD in post-apocalyptic Detroit. Connect to savsoul.com on port 4000, or port 4001 with TLS.">
<link rel="stylesheet" href="/site.css"><link rel="canonical" href="https://savsoul.com/{'' if filename=='index.html' else filename}">{terminal_assets}</head>
<body><a class="skip" href="#main">Skip to content</a><header class="shell"><a class="brand" href="/" aria-label="The Savage Soul home"><img src="/images/header.png" width="1000" alt="The Savage Soul: Scorched Earth"></a><nav aria-label="Main navigation">{links}<a class="nav-play" href="/playnow.html">Connect <span aria-hidden="true">↗</span></a></nav></header>
<main class="shell" id="main">{content}</main>
<footer class="shell"><p>The Savage Soul · Scorched Earth <span>© 2015–2026 Shelter 7</span></p><p><a href="/playnow.html">savsoul.com:4000</a> <span>Secure connection: port 4001 with TLS</span></p></footer></body></html>'''

def connections():
    return '''<aside class="connect-panel" aria-labelledby="connection-heading"><p class="eyebrow">Your way into the wasteland</p><h2 id="connection-heading">Connect to the MUD</h2><dl><div><dt>Host</dt><dd>savsoul.com</dd></div><div><dt>Standard port</dt><dd class="port">4000</dd></div><div><dt>Secure port · SSL/TLS on</dt><dd>4001</dd></div></dl><a class="button" href="/howtoplay.html">Set up your client <span aria-hidden="true">→</span></a><p class="small">Free to play. Bring a MUD client and your curiosity.</p></aside>'''

PAGES={
'index.html':('Scorched Earth',f'''<section class="hero"><div><p class="eyebrow">Detroit, 2195 · A free text adventure</p><h1>Survive<br><span>Scorched Earth.</span></h1><p class="lead">Civilization fell. Magic, monsters and salvaged technology took its place. Step into Royal Oak and find your way through the ruins of a changed world.</p><div class="actions"><a class="button" href="/playnow.html">Start playing</a><a class="text-link" href="/world.html">Read the world history →</a></div><p class="status"><span aria-hidden="true">◆</span> Restoration in progress · The Savage Soul Dev</p></div>{connections()}</section>
<section class="features" aria-label="Explore the game"><article><p class="number">01 / Explore</p><h2>Beyond the city gate</h2><p>Visit Royal Oak’s streets and shops, search the inn, and uncover a route into the mist-covered ruins beyond the walls.</p></article><article><p class="number">02 / Develop</p><h2>Make your own survivor</h2><p>Earn XP through adventure. Train attributes, learn Peculiarities, and ask Tully how to develop your character.</p></article><article><p class="number">03 / Customize</p><h2>Play at your pace</h2><p>Choose your combat detail and prompt. Screen reader mode provides plain text, concise output and no ASCII maps.</p></article></section>
<section class="notice"><div><p class="eyebrow">Latest news · October 19, 2026</p><h2>The Savage Soul moves to Grim.</h2><p>A new engine and server, restored areas, updated combat and XP, shops, crafting, and better accessibility. Restoration continues.</p></div><a class="text-link" href="/news.html">Restoration notes →</a></section>'''),
'playnow.html':('Connect',f'''<div class="page-heading"><p class="eyebrow">Enter Royal Oak</p><h1>Connect and play.</h1><p class="lead">Use your preferred MUD client with the connection details below.</p></div><section class="two-column">{connections()}<div class="prose"><h2>Using Mudlet</h2><ol><li>Open Mudlet and add a new profile named <strong>The Savage Soul</strong>.</li><li>Set the server address to <code>savsoul.com</code> and the port to <code>4000</code>, with SSL off.</li><li>For an encrypted connection, use port <code>4001</code> and enable SSL instead. The certificate is publicly trusted for <code>savsoul.com</code>.</li><li>Connect and follow the account and character prompts.</li></ol><a class="button secondary" href="https://www.mudlet.org/">Get Mudlet</a><h2>Playing from a terminal</h2><pre><code>telnet savsoul.com 4000</code></pre><p>The website provides connection instructions; there is no embedded browser client on this page.</p><p><a href="/howtoplay.html">First steps and accessibility settings →</a></p></div></section>'''),
'howtoplay.html':('How to play','''<div class="page-heading"><p class="eyebrow">Getting started</p><h1>Your first steps.</h1><p class="lead">A MUD is a shared world explored through text. Type a command, read what happens, and choose your next move.</p></div><div class="prose wide"><section><h2>1. Connect</h2><p>Use <strong>savsoul.com</strong>, port <strong>4000</strong> with SSL off. For encryption, use port <strong>4001</strong> with SSL enabled. <a href="/playnow.html">Full connection instructions</a>.</p></section><section><h2>2. Create or select your character</h2><p>Follow the login prompts to create an account and character, or use your existing character name or account email. Your character’s progress is saved on the server.</p></section><section><h2>3. Look around</h2><div class="table-scroll"><table><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>look</code></td><td>Describe your room, its exits and what is here.</td></tr><tr><td><code>north</code>, <code>n</code></td><td>Move through an available exit; other directions work the same way.</td></tr><tr><td><code>look sign</code>, <code>read sign</code></td><td>Examine scenery and read signs.</td></tr><tr><td><code>inventory</code></td><td>See what you are carrying.</td></tr><tr><td><code>score</code></td><td>Review your character.</td></tr><tr><td><code>help</code>, <code>commands</code></td><td>Find help topics and available commands.</td></tr></tbody></table></div></section><section><h2>4. Make the display comfortable</h2><p>Your first login asks about screen reader use. You can change this at any time with <code>screenreader on</code> or <code>screenreader off</code>.</p><p>Try <code>combatlog brief</code>, <code>combatlog normal</code> or <code>combatlog detailed</code>. Use <code>prompt status</code> for more character detail, or <code>prompt off</code> for no prompt. These preferences are saved.</p></section><section><h2>5. Ask for guidance</h2><p>Explore Royal Oak, read the signs, and talk to the people you meet. Tully can answer questions about training and XP: <code>ask tully how can I become tougher?</code></p></section></div>'''),
'docs.html':('Help','''<div class="page-heading"><p class="eyebrow">Player reference</p><h1>Find your footing.</h1><p class="lead">The in-game help is the current reference for the restored MUD.</p></div><div class="features"><article><h2>Exploration &amp; equipment</h2><p><code>help look</code><br><code>help get</code><br><code>help inventory</code><br><code>help shops</code></p></article><article><h2>Character &amp; combat</h2><p><code>help combat</code><br><code>help train</code><br><code>help pecs</code><br><code>ask tully about spending xp</code></p></article><article><h2>Display &amp; accessibility</h2><p><code>help screenreader</code><br><code>help combatlog</code><br><code>help prompt</code><br><code>help config</code></p></article></div><section class="prose"><h2>New to text adventures?</h2><p>Start with the <a href="/howtoplay.html">getting-started guide</a>. Type <code>help</code> in the game to browse topics, or <code>commands</code> to list available commands.</p><h2>Original documentation</h2><p>The <a href="/muddocs/player-handbook.html">original player handbook</a> and <a href="/muddocs/races.html">race descriptions</a> are retained as historical references. They describe the original LPC game and may differ from the current restoration.</p></section>'''),
'maps.html':('Maps','''<div class="page-heading"><p class="eyebrow">Surveying the ruins</p><h1>Maps of the old world.</h1><p class="lead">Original planning maps, preserved for exploration and world history. Some routes may differ in the restored game; check the exits shown in your room.</p></div><div class="map-grid">'''+''.join(f'<figure><a href="/plan/{file}"><img loading="lazy" src="/plan/{file}" alt="Original {label} planning map"></a><figcaption>{label} <a href="/plan/{file}">Open full map ↗</a></figcaption></figure>' for file,label in [('Master.jpg','Detroit'),('RoyalOak.jpg','Royal Oak'),('SouthOfRoyalOak.jpg','South of Royal Oak')])+'''</div>'''),
'who.html':('Players','''<div class="page-heading"><p class="eyebrow">The community</p><h1>Who’s in the world?</h1><p class="lead">Connect to the MUD and type <code>who</code> to see who is playing.</p><a class="button" href="/playnow.html">Connection details</a></div>'''),
'bugs.html':('Help with a problem','''<div class="page-heading"><p class="eyebrow">Restoration in progress</p><h1>Something out of place?</h1><p class="lead">The world is being recovered from older files. Your observations help us find gaps.</p></div><div class="prose"><p>When reporting a problem to a wizard, include the room name, the command you typed, what happened and what you expected. A short transcript is especially useful.</p><p>The old website’s bug list belongs to the original game. It does not track the current restoration.</p><p><a href="/docs.html">Check the current help →</a></p></div>'''),
'beastiary.html':('People and creatures','''<div class="page-heading"><p class="eyebrow">The changed world</p><h1>People of Scorched Earth.</h1><p class="lead">The original setting’s people and creatures are being recovered alongside its places.</p></div><div class="prose"><h2>Original race reference</h2><p><a href="/muddocs/races.html">Read the archived race descriptions</a>. These describe the original setting; available character options and implemented abilities may differ in the current game.</p><h2>Learn about what you meet</h2><p>Use <code>look &lt;name&gt;</code> to examine someone in your room. Read descriptions carefully: people such as Tully can answer questions, while shopkeepers respond to <code>list</code>.</p></div>''')}

def build():
    OUT.mkdir(exist_ok=True)
    world=(ROOT/'content/world.html').read_text(encoding='utf8')
    news=(ROOT/'content/news.html').read_text(encoding='utf8')
    pages=dict(PAGES)
    browser='''<section aria-label="Browser MUD terminal"><div class="terminal-heading"><div><p class="eyebrow">No download needed</p><h1>Play in your browser.</h1><p>Your connection is encrypted. Use your usual MUD account or create one at the login prompt.</p></div><div class="terminal-tools"><button class="button" id="terminal-connect" type="button">Connect</button><button class="button secondary" id="terminal-disconnect" type="button" disabled>Disconnect</button><button class="button secondary" id="terminal-clear" type="button">Clear screen</button></div></div><p class="terminal-status" id="terminal-status" role="status">Select Connect to begin.</p><div class="terminal-frame"><div id="mud-terminal" aria-label="MUD output"></div><form id="terminal-command" class="terminal-form" autocomplete="off"><label for="mud-command" id="command-label">Command or login response</label><input id="mud-command" name="mud-command" type="password" maxlength="2048" autocomplete="off" autocapitalize="off" spellcheck="false" disabled><button class="button" type="submit" disabled>Send</button></form></div><div class="terminal-preferences"><label><input type="checkbox" id="terminal-reader">Screen reader support for this terminal</label><span>After login, use <code>screenreader on</code> for plain game output.</span></div><noscript><p>This terminal needs JavaScript. You can also use a MUD client with the connection details below.</p></noscript></section>'''
    instructions=PAGES['playnow.html'][1].split('<section class="two-column">',1)[1]
    instructions=instructions.replace('The website provides connection instructions; there is no embedded browser client on this page.','You can play in the browser terminal above, or use a dedicated client with these settings.')
    pages['playnow.html']=('Play in your browser',browser+'<details class="other-clients"><summary>Prefer Mudlet or another MUD client? Connection details</summary><section class="two-column">'+instructions+'</details>')
    pages['howtoplay.html']=(pages['howtoplay.html'][0],pages['howtoplay.html'][1].replace('<h2>1. Connect</h2>','<h2>1. Connect</h2><p><a href="/playnow.html">Play directly in your browser</a>, or use your favorite MUD client.</p>'))
    pages['world.html']=('World history','<div class="page-heading"><p class="eyebrow">Before Royal Oak</p><h1>After the Great Destruction.</h1><p class="lead">The original history of Scorched Earth.</p></div><article class="prose">'+world+'</article>')
    pages['news.html']=('Restoration notes','<div class="page-heading"><p class="eyebrow">From the ruins</p><h1>Restoration notes.</h1></div><article class="prose"><h2>October 19, 2026 · The Savage Soul moves to Grim</h2><p>We’ve moved from Dead Souls/LPC to Grim on a new server. Recovered areas return with Savage Soul combat and XP, shops, crafting, screen reader support, customizable prompts and Intermud chat. Restoration continues.</p><p>Connect to <strong>savsoul.com:4000</strong>, or use <strong>4001</strong> with SSL enabled for a trusted encrypted connection.</p><h2>From the original archive</h2><p>The entries below document the original game. They are preserved for historical context.</p>'+news+'</article>')
    for name,(title,content) in pages.items():(OUT/name).write_text(page(name,title,content),encoding='utf8')
    (OUT/'index.au.html').write_text(page('index.html','Scorched Earth',PAGES['index.html'][1]),encoding='utf8')
    shutil.copyfile(ROOT/'site.css',OUT/'site.css')
    for name in ['terminal.js','terminal.css']:shutil.copyfile(ROOT/name,OUT/name)
    shutil.copytree(ROOT/'vendor',OUT/'vendor',dirs_exist_ok=True)
    print('Built',len(pages)+1,'pages and shared stylesheet.')

if __name__=='__main__':build()
